"""Fast Fibonacci using fast-doubling algorithm, O(log n)."""


def _fib_pair(n):  # kept for reference, see fib() below
    """Return (F(n), F(n+1)) using fast doubling."""
    if n == 0:
        return (0, 1)
    a, b = _fib_pair(n // 2)
    c = a * (2 * b - a)
    d = a * a + b * b
    if n % 2 == 0:
        return (c, d)
    else:
        return (d, c + d)


def fib(n):
    """Return the nth Fibonacci number.

    Uses fast-doubling algorithm with O(log n) complexity.
    fib(0) = 0, fib(1) = 1.
    Exact Python bigint arithmetic.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    # Iterative fast doubling
    result = (0, 1)  # (F(0), F(1))
